const pp=a=>a.map(([lo,la])=>GEO.P(lo,la));
/* map svg. o: {view:[x,y,w,h], rivers:[names]|true, lakes:true, grid:true, layer:(P,k)=>svg, aria, wd, fillR:color} ; k = zoom factor for sizes */
function mapSVG(o){o=o||{};const v=o.view||(o.pad?[-10,-14,GEO.W0+20,GEO.H0+28]:[0,0,GEO.W0,GEO.H0]);const k=GEO.W0/v[2];const P=GEO.P;const sw=x=>r2(x/k);
  let s=`<rect x="${v[0]}" y="${v[1]}" width="${v[2]}" height="${v[3]}" fill="var(--card)"/>`;
  const wat=(a,op)=>PG(pp(a),{f:'var(--accent)',fo:op==null?0.16:op});
  ['arc','pac','bal','blk','azv','cas'].forEach(w=>{s+=wat(GEO.WATER[w]);});
  if(o.grid!==false){let g='';for(let lo=40;lo<=180;lo+=20){const pts=[];for(let la=40;la<=84;la+=2)pts.push(P(lo,la));g+=PL(pts,{c:'var(--muted)',sw:sw(0.5),dash:`${sw(2)} ${sw(3)}`});}
    for(const la of [50,60,70,80]){const pts=[];for(let lo=15;lo<=195;lo+=3)pts.push(P(lo,la));g+=PL(pts,{c:'var(--muted)',sw:sw(0.5),dash:`${sw(2)} ${sw(3)}`});}s+=`<g opacity="0.6">${g}</g>`;}
  Object.values(GEO.FOR).forEach(a=>{s+=PG(pp(a),{f:'var(--card)',s:'var(--muted)',sw:sw(0.6)});});
  const land=a=>PG(pp(a),{f:o.fillR||'var(--hl)',fo:o.fillO==null?0.28:o.fillO,s:'var(--fig)',sw:sw(0.8)});
  s+=land(GEO.RUS);Object.values(GEO.ISL).forEach(a=>{s+=land(a);});GEO.KUR.forEach(([lo,la])=>{const [x,y]=P(lo,la);s+=CI(x,y,sw(1.1),{f:'var(--fig)'});});
  if(o.lakes!==false)['lad','one','bai','lgk'].forEach(w=>{s+=PG(pp(GEO.WATER[w]),{f:'var(--accent)',fo:0.55,s:'var(--accent)',sw:sw(0.5)});});
  if(o.rivers){const names=o.rivers===true?Object.keys(GEO.RIV):o.rivers;names.forEach(nm=>{s+=PL(pp(GEO.RIV[nm]),{c:'var(--accent)',sw:sw(o.rivW||1.2)});});}
  if(o.layer)s+=o.layer(P,k);
  return `<svg viewBox="${r2(v[0])} ${r2(v[1])} ${r2(v[2])} ${r2(v[3])}" width="${o.wd||340}" style="max-width:100%;height:auto;font-family:system-ui,sans-serif;touch-action:manipulation" role="img" aria-label="${o.aria||'Карта России'}">${s}</svg>`;}
const mapFig=o=>mapSVG(Object.assign({pad:true,wd:520},o));
/* numbered markers on the map (for tasks): pts=[[lo,la,label]] */
const mkNum=(pts,o)=>(P,k)=>{o=o||{};let s='';pts.forEach(([lo,la,lab])=>{const [x,y]=P(lo,la);const r=7/k;s+=CI(x,y,r,{f:o.f||'var(--bad)',s:'var(--card)',sw:1.2/k})+`<text x="${r2(x)}" y="${r2(y+3.6/k)}" text-anchor="middle" font-size="${r2(10/k)}" font-weight="700" fill="var(--card)">${lab}</text>`;});return s;};
const dot=(lo,la,lab,o)=>(P,k)=>{o=o||{};const [x,y]=P(lo,la);return CI(x,y,(o.r||3)/k,{f:o.f||'var(--bad)'})+(lab?TX(x+(o.dx||5)/k,y+(o.dy||4)/k,lab,{fs:r2((o.fs||10)/k),a:o.a||'start',c:o.c||'var(--ink)'}):'');};
const mapNum=(pts,o)=>{o=o||{};return mapSVG(Object.assign({pad:true,layer:(P,k)=>(o.extra?o.extra(P,k):'')+mkNum(pts,o)(P,k)},o));};
/* interactive map widget: items=[{k,name,lo,la,info}], modes */
function mapWidget(w,cfg){const VIEWS=cfg.views||{'Вся Россия':null};let mode=Object.keys(cfg.modes)[0],vname=Object.keys(VIEWS)[0],target=null,score=[0,0],picked=null;
  w.innerHTML=`<b>${cfg.title}</b><div style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0" class="mw-modes">${Object.keys(cfg.modes).map(m=>`<button class="btn ghost" data-m="${m}" style="padding:7px 11px">${m}</button>`).join('')}</div>
  ${Object.keys(VIEWS).length>1?`<div style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0" class="mw-views">${Object.keys(VIEWS).map(m=>`<button class="btn ghost" data-v="${m}" style="padding:5px 10px;font-size:14px">🔍 ${m}</button>`).join('')}</div>`:''}
  <div class="mw-map fig" style="margin:6px 0"></div><div class="mw-info" style="min-height:3.2em;line-height:1.5"></div>
  <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:6px;align-items:center"><button class="btn mw-quiz" style="padding:8px 14px">🎯 Найди на карте</button><span class="mw-score small"></span></div>`;
  const g=c=>w.querySelector(c);
  const draw=()=>{const items=cfg.modes[mode];const vb=VIEWS[vname];const view=!vb?null:vb.px?vb.px:GEO.box(...vb.box);
    g('.mw-map').innerHTML=mapSVG({view,pad:!view,wd:560,rivers:cfg.rivers,layer:(P,k)=>items.map(it=>{const [x,y]=P(it.lo,it.la);const on=picked===it.k;
      return `<g data-k="${it.k}" style="cursor:pointer">${CI(x,y,11/k,{f:'var(--card)',fo:0.01})}${CI(x,y,(on?6.5:5)/k,{f:on?'var(--ok)':(it.c||'var(--bad)'),s:'var(--card)',sw:1.2/k})}${(cfg.labels&&!target)||on?TX(x+(it.dx!=null?it.dx:7)/k,y+(it.dy!=null?it.dy:4)/k,it.short||it.name,{fs:r2(10/k),a:it.a||'start'}):''}</g>`;}).join('')});
    w.querySelectorAll('.mw-modes button').forEach(b=>b.className='btn'+(b.dataset.m===mode?'':' ghost'));
    w.querySelectorAll('.mw-views button').forEach(b=>b.className='btn'+(b.dataset.v===vname?'':' ghost'));
    g('.mw-score').textContent=score[1]?`Счёт: ${score[0]} из ${score[1]}`:'';};
  const ask=()=>{const items=cfg.modes[mode];target=pick(items.filter(i=>i!==target));picked=null;g('.mw-info').innerHTML=`🎯 Покажи на карте: <span class="out">${target.name}</span>`;draw();};
  w.querySelectorAll('.mw-modes button').forEach(b=>b.onclick=()=>{mode=b.dataset.m;target=null;picked=null;g('.mw-info').innerHTML=cfg.hint||'Нажми на точку на карте.';draw();});
  w.querySelectorAll('.mw-views button').forEach(b=>b.onclick=()=>{vname=b.dataset.v;draw();});
  g('.mw-quiz').onclick=ask;
  g('.mw-map').addEventListener('click',e=>{const el=e.target.closest('[data-k]');if(!el)return;const it=cfg.modes[mode].find(i=>i.k===el.dataset.k);if(!it)return;picked=it.k;
    if(target){score[1]++;if(it===target){score[0]++;g('.mw-info').innerHTML=`✅ Верно! Это <span class="out">${it.name}</span>. ${it.info||''}`;}else{g('.mw-info').innerHTML=`❌ Это ${it.name}, а нужно было найти <span class="out">${target.name}</span>. ${target.info||''}`;picked=target.k;}target=null;}
    else g('.mw-info').innerHTML=`<span class="out">${it.name}</span>. ${it.info||''}`;draw();});
  g('.mw-info').innerHTML=cfg.hint||'Нажми на точку на карте.';draw();}

