/* ---------- interactive theory ---------- */
function onTheory(root){
  const w=root.querySelector('#w-xs');
  if(w){let cur='rus';w.innerHTML=`<b>Разрез земной коры: нажми на участок</b><div id="xb" style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0">${XS.map(z=>`<button class="btn ghost" data-k="${z.k}" style="padding:5px 9px;font-size:13.5px">${z.name}</button>`).join('')}</div><div id="xp" class="fig"></div><div id="xt" style="line-height:1.55"></div>`;
    const u=()=>{const z=XS.find(q=>q.k===cur);w.querySelector('#xp').innerHTML=crossSec(cur);w.querySelector('#xt').innerHTML=`<span class="out">${z.name}</span><br><b>Структура:</b> ${z.s}<br><b>Возраст:</b> ${z.a}<br><b>Рельеф:</b> ${z.r}<br><b>Полезные ископаемые:</b> ${z.m}`;w.querySelectorAll('#xb button').forEach(b=>b.className='btn'+(b.dataset.k===cur?'':' ghost'));};
    w.querySelector('#xb').addEventListener('click',e=>{const b=e.target.closest('[data-k]');if(b){cur=b.dataset.k;u();}});
    w.querySelector('#xp').addEventListener('click',e=>{const sv=e.target.closest('svg');if(!sv)return;const r=sv.getBoundingClientRect();const x=(e.clientX-r.left)/r.width*332;const z=XS.find(q=>x>=q.x0&&x<q.x1);if(z){cur=z.k;u();}});u();}
  const gq=root.querySelector('#w-geo');
  if(gq){gq.innerHTML=`<b>Машина времени: двигай ползунок в прошлое</b><label>Сколько млн лет назад: <output id="go"></output><input type="range" id="gT" min="0" max="4000" step="5" value="300"></label><div id="gt" style="line-height:1.6"></div>`;
    const u=()=>{const t=+gq.querySelector('#gT').value;gq.querySelector('#go').textContent=N(t);const e=ERAS.find(x=>t<=x[1]&&t>=x[2])||ERAS[0];const day=t/4600*24;const hmin=24-day;const H=Math.floor(hmin),Mi=Math.floor((hmin-H)*60);
      gq.querySelector('#gt').innerHTML=`Эра: <span class="out">${e[0]}</span> (${e[1]}–${e[2]} млн лет назад)<br>${e[3]}<br><span class="small">Если вся история Земли — сутки, сейчас на часах ≈ ${H}:${String(Mi).padStart(2,'0')}.</span>`;};
    gq.querySelector('#gT').oninput=u;u();}
}
